 if(/[.!?] /.test(t)){const parts=t.split(/(?<=[.!?”]) (?=[A-ZÅÄÖ”+])/);if(parts.length>1){const tp=parts.map(x=>trText(x,depth+1));if(tp.some(x=>x!==null))return parts.map((x,i)=>tp[i]??x).join(' ')}}
